<script setup lang="ts">
const api=useApi(); const { data: orders, refresh }=await useAsyncData('admin-orders',()=>api.request<any[]>('/admin/orders').catch(()=>[]))
async function setStatus(id:string,status:string){await api.request(`/admin/orders/${id}/status`,{method:'POST',body:{status}});await refresh()}
</script>
<template><div><div class="mb-5"><p class="label-mono text-signal-deep">Commerce</p><h1 class="mt-1 font-display text-[clamp(2.2rem,3vw,2.7rem)] font-semibold tracking-[-.045em]">Marketplace orders.</h1><p class="mt-1 text-[11.5px] text-ink/45">Fulfilment and 8% take-rate ledger.</p></div><div class="a-card overflow-hidden"><table class="w-full text-left text-[11px]"><thead class="border-b border-ink/10 bg-paper"><tr class="font-mono text-[7.5px] uppercase tracking-[.08em] text-ink/35"><th class="px-4 py-2.5">Order</th><th class="px-4 py-2.5">Items</th><th class="px-4 py-2.5">Total</th><th class="px-4 py-2.5">Commission</th><th class="px-4 py-2.5">Status</th><th class="px-4 py-2.5">Date</th></tr></thead><tbody><tr v-for="o in orders" :key="o._id" class="border-t border-ink/10"><td class="px-4 py-3 font-mono text-[9px]">{{ o.ref }}</td><td class="px-4 py-3">{{ o.items?.map((i:any)=>i.name).join(', ') }}</td><td class="px-4 py-3">{{ money(o.total) }}</td><td class="px-4 py-3 text-mint-deep">{{ money(o.commission) }}</td><td class="px-4 py-3"><AppSelect :model-value="o.status" :options="['pending','paid','fulfilled','cancelled']" compact aria-label="Order status" @update:model-value="v => setStatus(o._id, String(v))" /></td><td class="px-4 py-3 text-ink/40">{{ shortDate(o.createdAt) }}</td></tr></tbody></table></div></div></template>
